CREATE OR REPLACE FUNCTION public.approve_financial_program_request(p_request_id uuid, p_snapshot jsonb, p_approved_by uuid)
 RETURNS program_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ declare v_row public.program_requests%rowtype; v_required text[]:=array[
  'affiliate_id','numero_control','financial_union','financial_employee_category','affiliation_status','fund','rate','term',
  'maxAmount','requestedAmount','administrativeFee','financialResult','google_export'];
begin
  if coalesce(auth.role(),'')<>'service_role' then raise exception 'SERVICE_ROLE_REQUIRED' using errcode='42501'; end if;
  select * into v_row from public.program_requests where id=p_request_id for update;
  if v_row.id is null or v_row.financial_processing_status is null then raise exception 'FINANCIAL_REQUEST_NOT_FOUND' using errcode='P0001'; end if;
  if v_row.financial_approval_snapshot is not null then return v_row; end if;
  if v_row.status not in ('requires_financial_processing','in_review') then raise exception 'FINANCIAL_REQUEST_NOT_APPROVABLE' using errcode='P0001'; end if;
  if jsonb_typeof(p_snapshot)<>'object' or exists(select 1 from unnest(v_required) k where not(p_snapshot?k)) then raise exception 'FINANCIAL_APPROVAL_SNAPSHOT_INCOMPLETE' using errcode='22023'; end if;
  if p_snapshot->>'affiliate_id'<>v_row.affiliate_id::text or p_snapshot->>'numero_control'<>v_row.numero_control then raise exception 'FINANCIAL_SNAPSHOT_IDENTITY_MISMATCH' using errcode='22023'; end if;
  if jsonb_typeof(p_snapshot->'administrativeFee')<>'object' or not((p_snapshot->'administrativeFee')?'rule') or not((p_snapshot->'administrativeFee')?'version') then raise exception 'ADMINISTRATIVE_FEE_CONTRACT_INCOMPLETE' using errcode='22023'; end if;
  if jsonb_typeof(p_snapshot->'google_export')<>'object' or jsonb_typeof(p_snapshot->'google_export'->'row')<>'array'
     or jsonb_array_length(p_snapshot->'google_export'->'row')<>38
     or p_snapshot->'google_export'->>'contract_version'<>'FINAL_APPROVED_LOAN_EXPORT_V1'
  then raise exception 'GOOGLE_EXPORT_CONTRACT_INCOMPLETE' using errcode='22023'; end if;
  if p_approved_by is null or not exists(select 1 from auth.users where id=p_approved_by) then raise exception 'APPROVAL_ACTOR_REQUIRED' using errcode='22023'; end if;
  update public.program_requests set status='approved',financial_processing_status='ready_for_handoff',financial_approval_snapshot=p_snapshot,
    financial_approved_at=now(),financial_approved_by=p_approved_by,updated_at=now() where id=p_request_id returning * into v_row;
  return v_row;
end $function$

CREATE OR REPLACE FUNCTION public.approve_financial_program_request(p_request_id uuid, p_snapshot jsonb, p_approved_by uuid, p_comment text)
 RETURNS program_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_row public.program_requests%rowtype;
  v_comment text:=nullif(btrim(coalesce(p_comment,'')),'');
  v_actor_label text;
  v_from_status text;
begin
  if coalesce(auth.role(),'')<>'service_role' then raise exception 'SERVICE_ROLE_REQUIRED' using errcode='42501'; end if;
  if v_comment is not null and length(v_comment) not between 3 and 2000 then
    raise exception 'PROGRAM_REQUEST_COMMENT_INVALID' using errcode='22023';
  end if;
  select status into v_from_status from public.program_requests where id=p_request_id for update;
  v_row:=public.approve_financial_program_request(p_request_id,p_snapshot,p_approved_by);
  select coalesce(
    nullif(btrim(raw_user_meta_data->>'display_name'),''),
    nullif(btrim(raw_user_meta_data->>'full_name'),''),
    nullif(btrim(raw_user_meta_data->>'name'),''),
    'Personal autorizado'
  ) into v_actor_label from auth.users where id=p_approved_by;
  insert into public.program_request_admin_events(
    request_id,actor_auth_user_id,actor_label,action,from_status,to_status,comment,client_action_id,created_at
  ) values(
    v_row.id,p_approved_by,left(coalesce(v_actor_label,'Personal autorizado'),160),'APPROVE',coalesce(v_from_status,'in_review'),'approved',
    v_comment,extensions.gen_random_uuid(),coalesce(v_row.financial_approved_at,now())
  ) on conflict(request_id) where action='APPROVE' do nothing;
  return v_row;
end $function$

CREATE OR REPLACE FUNCTION public.create_membership_request(p_membership_offering_id uuid, p_document_ids uuid[], p_phone text, p_rfc text, p_curp text, p_terms_version_id uuid, p_idempotency_key uuid)
 RETURNS program_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ declare v_affiliate public.affiliates%rowtype;v_row public.program_requests%rowtype;v_missing integer; begin
  select a.* into v_affiliate from public.affiliates a where a.id=public.get_effective_affiliate_id();
  if auth.uid() is null or v_affiliate.id is null then raise exception 'AFFILIATE_REQUIRED' using errcode='42501'; end if;
  if not exists(select 1 from public.membership_offerings where id=p_membership_offering_id and enabled) then raise exception 'MEMBERSHIP_UNAVAILABLE' using errcode='22023'; end if;
  if regexp_replace(coalesce(p_phone,''),'\D','','g')!~'^[0-9]{10}$' or upper(btrim(p_rfc))!~'^[A-ZÑ&]{3,4}[0-9]{6}[A-Z0-9]{3}$' or upper(btrim(p_curp))!~'^[A-Z]{4}[0-9]{6}[HM][A-Z]{5}[A-Z0-9][0-9]$' then raise exception 'INVALID_APPLICANT_PROFILE' using errcode='22023'; end if;
  if not exists(select 1 from public.program_terms_versions where id=p_terms_version_id and program_id='membership' and membership_offering_id=p_membership_offering_id and published) then raise exception 'TERMS_VERSION_REQUIRED' using errcode='22023'; end if;
  select count(*) into v_missing from public.program_document_requirements r where r.program_id='membership' and r.membership_offering_id=p_membership_offering_id and r.enabled and r.required and not exists(
    select 1 from public.affiliate_documents d where d.id=any(p_document_ids) and d.affiliate_id=v_affiliate.id and d.document_type_id=r.document_type_id and d.status in('PENDING_REVIEW','UNDER_REVIEW','VERIFIED'));
  if v_missing>0 then raise exception 'REQUIRED_DOCUMENTS_MISSING' using errcode='22023'; end if;
  select * into v_row from public.program_requests where affiliate_id=v_affiliate.id and idempotency_key=p_idempotency_key;
  if v_row.id is null then
    insert into public.program_requests(actor_real_auth_user_id,affiliate_id,numero_control,program_id,membership_offering_id,request_type,status,terms_accepted,terms_version_id,idempotency_key,applicant_profile_snapshot,source_context)
    values(auth.uid(),v_affiliate.id,v_affiliate.numero_control,'membership',p_membership_offering_id,'benefit','submitted',true,p_terms_version_id,p_idempotency_key,
      jsonb_build_object('phone',regexp_replace(p_phone,'\D','','g'),'rfc',upper(btrim(p_rfc)),'curp',upper(btrim(p_curp)),'source','request_snapshot'),jsonb_build_object('surface','membership_application')) returning * into v_row;
    perform public.attach_request_documents(v_row.id,p_document_ids);
  end if;return v_row;
end $function$

CREATE OR REPLACE FUNCTION public.create_program_request_with_documents(p_program_item_id uuid, p_product_id uuid, p_quantity integer, p_notes text, p_signature_data text, p_terms_accepted boolean, p_idempotency_key uuid, p_document_ids uuid[])
 RETURNS program_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_row public.program_requests%rowtype;v_missing integer;
begin
  v_row:=public.create_program_request(p_program_item_id,p_product_id,p_quantity,p_notes,p_signature_data,p_terms_accepted,p_idempotency_key);
  select count(*) into v_missing from jsonb_array_elements(coalesce(v_row.document_requirements_snapshot,'[]'::jsonb)) requirement
  where coalesce((requirement->>'required')::boolean,true) and not exists(
    select 1 from public.affiliate_documents d
    left join public.affiliate_files af on af.id=d.affiliate_file_id
    join public.private_assets pa on pa.id=coalesce(d.private_asset_id,af.private_asset_id) and pa.status='READY'
    join storage.objects so on so.bucket_id=pa.storage_bucket and so.name=pa.storage_path
    where d.id=any(coalesce(p_document_ids,array[]::uuid[])) and d.affiliate_id=v_row.affiliate_id
      and d.document_type_id=(requirement->>'document_type_id')::uuid and d.status in('PENDING_REVIEW','UNDER_REVIEW','VERIFIED')
      and not exists(select 1 from public.affiliate_documents newer where newer.affiliate_id=d.affiliate_id and newer.document_type_id=d.document_type_id and (newer.created_at,newer.id)>(d.created_at,d.id))
  );
  if v_missing>0 then raise exception 'REQUIRED_DOCUMENTS_MISSING' using errcode='22023'; end if;
  perform public.attach_request_documents(v_row.id,coalesce(p_document_ids,array[]::uuid[]));
  return v_row;
end $function$

CREATE OR REPLACE FUNCTION public.create_validated_financial_program_request(p_actor_real_auth_user_id uuid, p_affiliate_id uuid, p_impersonation_session_id uuid, p_program_item_id uuid, p_notes text, p_signature_data text, p_terms_version_id uuid, p_document_ids uuid[], p_idempotency_key uuid, p_amount numeric, p_term integer, p_term_semantics text, p_expected_profile_version integer, p_financial_submission_snapshot jsonb)
 RETURNS program_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_affiliate public.affiliates%rowtype;
  v_item public.program_catalog_items%rowtype;
  v_ctx public.impersonation_sessions%rowtype;
  v_row public.program_requests%rowtype;
  v_deposit public.loan_request_deposit_snapshots%rowtype;
  v_submission jsonb;
  v_phone text;
  v_bank_text text;
  v_missing integer;
begin
  v_bank_text:=nullif(btrim(coalesce(p_financial_submission_snapshot->'deposit_selection'->>'bank_account_id','')),'');
  if v_bank_text is not null then
    return public.create_validated_financial_program_request_bank_required(
      p_actor_real_auth_user_id,p_affiliate_id,p_impersonation_session_id,p_program_item_id,p_notes,
      p_signature_data,p_terms_version_id,p_document_ids,p_idempotency_key,p_amount,p_term,
      p_term_semantics,p_expected_profile_version,p_financial_submission_snapshot
    );
  end if;

  if coalesce(auth.role(),'')<>'service_role' then raise exception 'SERVICE_ROLE_REQUIRED' using errcode='42501'; end if;
  if p_actor_real_auth_user_id is null or not exists(select 1 from auth.users where id=p_actor_real_auth_user_id) then
    raise exception 'AUTH_ACTOR_REQUIRED' using errcode='42501';
  end if;
  select * into v_affiliate from public.affiliates where id=p_affiliate_id for update;
  if v_affiliate.id is null or v_affiliate.financial_profile_version<>p_expected_profile_version then
    raise exception 'CONDITIONS_CHANGED' using errcode='PT409';
  end if;
  if p_impersonation_session_id is null then
    if v_affiliate.auth_user_id is distinct from p_actor_real_auth_user_id then raise exception 'AFFILIATE_CONTEXT_DENIED' using errcode='42501'; end if;
  else
    select * into v_ctx from public.impersonation_sessions where id=p_impersonation_session_id for share;
    if v_ctx.id is null or v_ctx.actor_real_auth_user_id<>p_actor_real_auth_user_id
       or v_ctx.usuario_contexto_affiliate_id<>p_affiliate_id or v_ctx.ended_at is not null or v_ctx.expires_at<=now()
       or not exists(select 1 from public.admin_assignments a join public.admin_roles r on r.id=a.role_id and r.enabled where a.auth_user_id=p_actor_real_auth_user_id and a.enabled) then
      raise exception 'IMPERSONATION_CONTEXT_INVALID' using errcode='42501';
    end if;
  end if;
  select * into v_item from public.program_catalog_items
   where id=p_program_item_id and program_key='prestamo' and enabled and request_mode='supabase' and legacy_boundary;
  if v_item.id is null then raise exception 'PROGRAM_NOT_REQUESTABLE' using errcode='22023'; end if;
  if p_idempotency_key is null then raise exception 'IDEMPOTENCY_KEY_REQUIRED' using errcode='22023'; end if;
  if nullif(btrim(coalesce(p_signature_data,'')),'') is null then raise exception 'SIGNATURE_AND_TERMS_REQUIRED' using errcode='22023'; end if;
  if p_amount is null or p_amount<=0 or p_term is null or p_term<=0 or length(btrim(coalesce(p_term_semantics,''))) not between 3 and 80 then
    raise exception 'FINANCIAL_REQUEST_TERMS_INVALID' using errcode='22023';
  end if;
  if not exists(select 1 from public.program_terms_versions where id=p_terms_version_id and program_id='prestamo' and membership_offering_id is null and published) then
    raise exception 'TERMS_VERSION_REQUIRED' using errcode='22023';
  end if;
  if p_financial_submission_snapshot is null
     or jsonb_typeof(p_financial_submission_snapshot)<>'object'
     or not(p_financial_submission_snapshot ?& array[
       'affiliate_id','actor_real_auth_user_id','profile_version','profile_fingerprint',
       'criteria_source_fingerprint','term_policy_fingerprint','calculation_contract_version',
       'criterion_identity','financialResult','confirmed_at','deposit_selection'
     ])
     or jsonb_typeof(p_financial_submission_snapshot->'financialResult')<>'object'
     or jsonb_typeof(p_financial_submission_snapshot->'deposit_selection')<>'object'
     or nullif(btrim(coalesce(p_financial_submission_snapshot->'deposit_selection'->>'bank_account_id','')),'') is not null
     or p_financial_submission_snapshot->>'affiliate_id'<>p_affiliate_id::text
     or p_financial_submission_snapshot->>'actor_real_auth_user_id'<>p_actor_real_auth_user_id::text
     or coalesce(p_financial_submission_snapshot->>'impersonation_session_id','')<>coalesce(p_impersonation_session_id::text,'')
     or (p_financial_submission_snapshot->>'profile_version')::integer<>p_expected_profile_version
     or (p_financial_submission_snapshot->'financialResult'->>'amount')::numeric<>p_amount
     or (p_financial_submission_snapshot->'financialResult'->>'paymentCount')::integer<>p_term then
    raise exception 'FINANCIAL_SUBMISSION_CONTRACT_MISMATCH' using errcode='22023';
  end if;
  v_phone:=p_financial_submission_snapshot->'deposit_selection'->>'notification_phone';
  if coalesce(v_phone,'') !~ '^[0-9]{10}$' then raise exception 'INVALID_NOTIFICATION_PHONE' using errcode='22023'; end if;

  v_submission:=(p_financial_submission_snapshot-'deposit_selection') || jsonb_build_object('deposit',jsonb_build_object(
    'bank_account_id',null,'bank_name',null,'masked_card',null,'masked_clabe',null,
    'masked_phone','••• ••• '||right(v_phone,4)
  ));

  select count(*) into v_missing from public.program_document_requirements r
   where r.program_id='prestamo' and r.membership_offering_id is null and r.enabled and r.required and not exists(
     select 1 from public.affiliate_documents d where d.id=any(coalesce(p_document_ids,array[]::uuid[]))
       and d.affiliate_id=p_affiliate_id and d.document_type_id=r.document_type_id
       and d.status in('PENDING_REVIEW','UNDER_REVIEW','VERIFIED'));
  if v_missing>0 then raise exception 'REQUIRED_DOCUMENTS_MISSING' using errcode='22023'; end if;

  select * into v_row from public.program_requests where affiliate_id=p_affiliate_id and idempotency_key=p_idempotency_key;
  if v_row.id is not null then
    if v_row.actor_real_auth_user_id<>p_actor_real_auth_user_id or v_row.program_id<>'prestamo'
       or v_row.program_item_id<>p_program_item_id or v_row.requested_amount<>p_amount or v_row.requested_term<>p_term then
      raise exception 'IDEMPOTENCY_CONTRACT_MISMATCH' using errcode='22023';
    end if;
    select * into v_deposit from public.loan_request_deposit_snapshots where request_id=v_row.id;
    if v_deposit.request_id is null or v_deposit.source_bank_account_id is not null or v_deposit.notification_phone<>v_phone then
      raise exception 'IDEMPOTENCY_CONTRACT_MISMATCH' using errcode='22023';
    end if;
    return v_row;
  end if;

  insert into public.program_requests(
    actor_real_auth_user_id,affiliate_id,usuario_contexto_affiliate_id,impersonation_session_id,impersonation_reason,
    numero_control,program_id,program_item_id,request_type,status,quantity,notes,signature_data,terms_accepted,
    terms_version_id,source_context,financial_processing_status,idempotency_key,requested_amount,requested_term,
    requested_term_semantics,financial_submission_snapshot
  ) values(
    p_actor_real_auth_user_id,p_affiliate_id,case when v_ctx.id is null then null else p_affiliate_id end,v_ctx.id,v_ctx.reason,
    v_affiliate.numero_control,'prestamo',v_item.id,'quote','requires_financial_processing',1,
    left(nullif(btrim(coalesce(p_notes,'')),''),2000),p_signature_data,true,p_terms_version_id,
    jsonb_build_object('source','sutiapp','financial_confirmation','SUPABASE_REVALIDATED','assisted',v_ctx.id is not null),
    'pending',p_idempotency_key,p_amount,p_term,btrim(p_term_semantics),v_submission
  ) returning * into v_row;

  insert into public.loan_request_deposit_snapshots(request_id,affiliate_id,notification_phone)
  values(v_row.id,p_affiliate_id,v_phone);
  insert into public.sensitive_change_audit(actor_auth_user_id,affiliate_id,resource,action,target_id,metadata)
  values(p_actor_real_auth_user_id,p_affiliate_id,'program_requests','LOAN_DEPOSIT_CONFIRMED',v_row.id,
    jsonb_build_object('has_bank_account',false,'phone_last4',right(v_phone,4)));

  insert into public.request_documents(request_id,document_type_id,affiliate_document_id,private_asset_id,asset_sha256,status_at_submission)
  select v_row.id,d.document_type_id,d.id,coalesce(d.private_asset_id,af.private_asset_id),pa.content_sha256,d.status
  from public.affiliate_documents d left join public.affiliate_files af on af.id=d.affiliate_file_id
  join public.private_assets pa on pa.id=coalesce(d.private_asset_id,af.private_asset_id)
  where d.id=any(coalesce(p_document_ids,array[]::uuid[])) and d.affiliate_id=p_affiliate_id
    and d.status in('PENDING_REVIEW','UNDER_REVIEW','VERIFIED')
  on conflict(request_id,document_type_id) do nothing;
  return v_row;
exception when unique_violation then
  select * into v_row from public.program_requests where affiliate_id=p_affiliate_id and idempotency_key=p_idempotency_key;
  if v_row.id is not null then
    if v_row.actor_real_auth_user_id<>p_actor_real_auth_user_id or v_row.program_id<>'prestamo'
       or v_row.program_item_id<>p_program_item_id or v_row.requested_amount<>p_amount or v_row.requested_term<>p_term then
      raise exception 'IDEMPOTENCY_CONTRACT_MISMATCH' using errcode='22023';
    end if;
    select * into v_deposit from public.loan_request_deposit_snapshots where request_id=v_row.id;
    if v_deposit.request_id is null or v_deposit.source_bank_account_id is not null or v_deposit.notification_phone<>v_phone then
      raise exception 'IDEMPOTENCY_CONTRACT_MISMATCH' using errcode='22023';
    end if;
    return v_row;
  end if;
  raise;
end $function$

CREATE OR REPLACE FUNCTION public.create_validated_program_product_payment_request(p_actor_real_auth_user_id uuid, p_affiliate_id uuid, p_impersonation_session_id uuid, p_program_item_id uuid, p_notes text, p_signature_data text, p_terms_version_id uuid, p_document_ids uuid[], p_idempotency_key uuid, p_down_payment numeric, p_term integer, p_expected_profile_version integer, p_schedule_anchor_date date)
 RETURNS program_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_affiliate public.affiliates%rowtype;
  v_item public.program_catalog_items%rowtype;
  v_ctx public.impersonation_sessions%rowtype;
  v_quote public.program_requests%rowtype;
  v_row public.program_requests%rowtype;
  v_policy public.loan_term_policy%rowtype;
  v_rules jsonb;
  v_rule jsonb;
  v_rule_count integer;
  v_price numeric(14,2);
  v_amount numeric(14,2);
  v_source text;
  v_result jsonb;
  v_schedule jsonb;
  v_process text;
  v_period text;
  v_union_label text;
  v_category_label text;
  v_missing integer;
  v_snapshot jsonb;
  v_business_date date:=(now() at time zone 'America/Hermosillo')::date;
begin
  if coalesce(auth.role(),'')<>'service_role' then raise exception 'SERVICE_ROLE_REQUIRED' using errcode='42501'; end if;
  if p_actor_real_auth_user_id is null or not exists(select 1 from auth.users where id=p_actor_real_auth_user_id) then
    raise exception 'AUTH_ACTOR_REQUIRED' using errcode='42501';
  end if;
  select * into v_affiliate from public.affiliates where id=p_affiliate_id for update;
  if v_affiliate.id is null or v_affiliate.financial_profile_version<>p_expected_profile_version then
    raise exception 'CONDITIONS_CHANGED' using errcode='PT409';
  end if;
  if p_impersonation_session_id is null then
    if v_affiliate.auth_user_id is distinct from p_actor_real_auth_user_id then raise exception 'AFFILIATE_CONTEXT_DENIED' using errcode='42501'; end if;
  else
    select * into v_ctx from public.impersonation_sessions where id=p_impersonation_session_id for share;
    if v_ctx.id is null or v_ctx.actor_real_auth_user_id<>p_actor_real_auth_user_id
       or v_ctx.usuario_contexto_affiliate_id<>p_affiliate_id or v_ctx.ended_at is not null or v_ctx.expires_at<=now()
       or not exists(select 1 from public.admin_assignments a join public.admin_roles r on r.id=a.role_id and r.enabled
         where a.auth_user_id=p_actor_real_auth_user_id and a.enabled) then
      raise exception 'IMPERSONATION_CONTEXT_INVALID' using errcode='42501';
    end if;
  end if;
  select * into v_item from public.program_catalog_items where id=p_program_item_id and enabled and request_mode='supabase' for share;
  if v_item.id is null or v_item.program_key='prestamo' then raise exception 'PROGRAM_PRODUCT_NOT_FINANCEABLE' using errcode='22023'; end if;
  if v_item.requires_quote then
    select * into v_quote from public.program_requests
    where affiliate_id=p_affiliate_id and program_item_id=v_item.id and request_type='quote' and status='approved'
      and quoted_amount>0 and (valid_until is null or valid_until>=v_business_date)
    order by responded_at desc nulls last,created_at desc,id desc limit 1 for share;
    if v_quote.id is null then raise exception 'AUTHORIZED_PRODUCT_PRICE_UNAVAILABLE' using errcode='P0001'; end if;
    v_price:=v_quote.quoted_amount;v_source:='APPROVED_QUOTE';
  else
    if v_item.price_cash is null or v_item.price_cash<=0 then raise exception 'AUTHORIZED_PRODUCT_PRICE_UNAVAILABLE' using errcode='P0001'; end if;
    v_price:=v_item.price_cash;v_source:='PRICE_CASH';
  end if;
  if p_down_payment is null or p_down_payment<0 or p_down_payment>=v_price then raise exception 'DOWN_PAYMENT_OUT_OF_RANGE' using errcode='22023'; end if;
  v_amount:=round(v_price-p_down_payment,2);
  select * into v_policy from public.loan_term_policy where id='primary' and enabled;
  if v_policy.id is null then raise exception 'LOAN_TERM_POLICY_UNAVAILABLE' using errcode='P0001'; end if;
  select u.label,c.label into v_union_label,v_category_label
  from public.affiliates a
  left join public.segmentation_catalog_entries u on u.catalog_type='union' and u.code=a.financial_union_code and u.enabled
  left join public.segmentation_catalog_entries c on c.catalog_type='employment_category' and c.code=a.financial_employee_category_code and c.enabled
  where a.id=v_affiliate.id;
  if v_union_label is null or v_category_label is null then raise exception 'AFFILIATE_FINANCIAL_PROFILE_INCOMPLETE' using errcode='P0001'; end if;
  v_rules:=public.get_financial_runtime_rules();
  select count(*) into v_rule_count
  from jsonb_array_elements(v_rules) candidate(value)
  where value->>'program_id'='caja'
    and public.normalize_suti_financial_key(value->>'category')=public.normalize_suti_financial_key(v_category_label)
    and public.normalize_suti_financial_key(value->>'union')=public.normalize_suti_financial_key(v_union_label)
    and case upper(coalesce(value->>'visibility_mode','AUTO'))
      when 'MOSTRAR' then true when 'OCULTAR' then false
      else value->>'available_on' is null or (value->>'available_on')::date between v_business_date
        and (date_trunc('month',v_business_date)+interval '5 months - 1 day')::date end;
  if v_rule_count<>1 then raise exception 'CAJA_CHICA_RULE_NOT_ELIGIBLE' using errcode='P0001'; end if;
  select value into v_rule
  from jsonb_array_elements(v_rules) candidate(value)
  where value->>'program_id'='caja'
    and public.normalize_suti_financial_key(value->>'category')=public.normalize_suti_financial_key(v_category_label)
    and public.normalize_suti_financial_key(value->>'union')=public.normalize_suti_financial_key(v_union_label)
    and case upper(coalesce(value->>'visibility_mode','AUTO'))
      when 'MOSTRAR' then true when 'OCULTAR' then false
      else value->>'available_on' is null or (value->>'available_on')::date between v_business_date
        and (date_trunc('month',v_business_date)+interval '5 months - 1 day')::date end
  limit 1;
  v_rule:=v_rule||jsonb_build_object('status','AVAILABLE');
  v_result:=public.resolve_suti_loan_quote_contract(
    jsonb_build_array(v_rule),v_union_label,v_category_label,
    v_rule->>'id',v_amount,p_term,jsonb_build_object(
      'source','SUPABASE_LOAN_TERM_POLICY','standardTerms',v_policy.standard_terms,
      'customMinTerm',v_policy.custom_min_term,'customStep',v_policy.custom_step,
      'decisionReference',v_policy.decision_reference
    )
  );
  v_process:=case v_affiliate.financial_employee_category_code
    when 'SUPLENTES_VARIABLES' then '3' when 'JUBILADOS_PENSIONADOS' then 'JUB'
    when 'SUPLENTES_FIJOS' then '1' when 'EVENTUALES' then '1' when 'BASE' then '1'
    else null end;
  if v_process is null then raise exception 'PAYROLL_PROCESS_UNRESOLVED' using errcode='P0001'; end if;
  v_period:=case when v_process='JUB' then 'mensual' else 'quincenal' end;
  v_result:=(v_result||jsonb_build_object('paymentPeriod',v_period,'ratePeriod',v_period,'source','SUPABASE_FINANCIAL_CRITERIA'));
  if p_schedule_anchor_date is distinct from v_business_date then raise exception 'SCHEDULE_ANCHOR_CHANGED' using errcode='PT409'; end if;
  v_schedule:=public.generate_program_product_payment_schedule(
    p_schedule_anchor_date,v_process,(v_result->>'paymentCount')::integer,
    (v_result->>'total')::numeric,(v_result->>'paymentPerPeriod')::numeric
  );
  if p_idempotency_key is null then raise exception 'IDEMPOTENCY_KEY_REQUIRED' using errcode='22023'; end if;
  if nullif(btrim(coalesce(p_signature_data,'')),'') is null then raise exception 'SIGNATURE_AND_TERMS_REQUIRED' using errcode='22023'; end if;
  if not exists(select 1 from public.program_terms_versions where id=p_terms_version_id and program_id='prestamo'
    and membership_offering_id is null and published) then raise exception 'TERMS_VERSION_REQUIRED' using errcode='22023'; end if;
  select count(*) into v_missing
  from public.resolve_effective_document_requirements('PROGRAM','prestamo') requirement
  where requirement.required and not exists(
    select 1 from public.affiliate_documents d
    left join public.affiliate_files af on af.id=d.affiliate_file_id
    join public.private_assets pa on pa.id=coalesce(d.private_asset_id,af.private_asset_id) and pa.status='READY'
    join storage.objects so on so.bucket_id=pa.storage_bucket and so.name=pa.storage_path
    where d.id=any(coalesce(p_document_ids,array[]::uuid[])) and d.affiliate_id=p_affiliate_id
      and d.document_type_id=requirement.document_type_id and d.status in('PENDING_REVIEW','UNDER_REVIEW','VERIFIED')
      and not exists(select 1 from public.affiliate_documents newer where newer.affiliate_id=d.affiliate_id
        and newer.document_type_id=d.document_type_id and (newer.created_at,newer.id)>(d.created_at,d.id))
  );
  if v_missing>0 then raise exception 'REQUIRED_DOCUMENTS_MISSING' using errcode='22023'; end if;
  v_snapshot:=jsonb_build_object(
    'contract_version','PROGRAM_PRODUCT_PAYMENT_V1','calculation_contract_version','SUTI_LOAN_QUOTE_V1',
    'calendar_contract_version','PROGRAM_PRODUCT_PAYROLL_CALENDAR_V1','affiliate_id',p_affiliate_id,
    'actor_real_auth_user_id',p_actor_real_auth_user_id,'impersonation_session_id',p_impersonation_session_id,
    'profile_version',v_affiliate.financial_profile_version,'product',jsonb_build_object(
      'program_item_id',v_item.id,'program_key',v_item.program_key,'name',v_item.name
    ),'authorized_price',v_price,'price_source',v_source,'quote_request_id',v_quote.id,
    'down_payment',round(p_down_payment,2),'financed_amount',v_amount,'fund_program_id','caja',
    'fund_rule_id',v_rule->>'rule_id','criterion_identity',v_rule->>'criterion_identity',
    'financial_authority','SUPABASE','financial_rules_source_hash',v_rule->>'source_snapshot_hash',
    'financialResult',v_result,'payment_schedule',v_schedule,'terms_version_id',p_terms_version_id,
    'confirmed_at',now()
  );
  select * into v_row from public.program_requests where affiliate_id=p_affiliate_id and idempotency_key=p_idempotency_key;
  if v_row.id is not null then
    if v_row.actor_real_auth_user_id<>p_actor_real_auth_user_id or v_row.program_item_id<>p_program_item_id
       or v_row.requested_amount<>v_amount or v_row.requested_term<>p_term
       or (v_row.financial_submission_snapshot->>'down_payment')::numeric<>round(p_down_payment,2)
       or v_row.financial_submission_snapshot->>'price_source'<>v_source
       or coalesce(v_row.financial_submission_snapshot->>'quote_request_id','')<>coalesce(v_quote.id::text,'') then
      raise exception 'IDEMPOTENCY_CONTRACT_MISMATCH' using errcode='22023';
    end if;
    return v_row;
  end if;
  insert into public.program_requests(
    actor_real_auth_user_id,affiliate_id,usuario_contexto_affiliate_id,impersonation_session_id,impersonation_reason,
    numero_control,program_id,program_item_id,request_type,status,quantity,notes,signature_data,terms_accepted,
    terms_version_id,source_context,financial_processing_status,idempotency_key,requested_amount,requested_term,
    requested_term_semantics,financial_submission_snapshot
  ) values(
    p_actor_real_auth_user_id,p_affiliate_id,case when v_ctx.id is null then null else p_affiliate_id end,v_ctx.id,v_ctx.reason,
    v_affiliate.numero_control,v_item.program_key,v_item.id,'benefit','requires_financial_processing',1,
    left(nullif(btrim(coalesce(p_notes,'')),''),2000),p_signature_data,true,p_terms_version_id,
    jsonb_build_object('source','sutiapp','flow','PROGRAM_PRODUCT_PAYMENT_V1','price_source',v_source,
      'quote_request_id',v_quote.id,'fund_program_id','caja','assisted',v_ctx.id is not null),
    'pending',p_idempotency_key,v_amount,p_term,v_period,v_snapshot
  ) returning * into v_row;
  insert into public.request_documents(request_id,document_type_id,affiliate_document_id,private_asset_id,asset_sha256,status_at_submission)
  select v_row.id,d.document_type_id,d.id,coalesce(d.private_asset_id,af.private_asset_id),pa.content_sha256,d.status
  from public.affiliate_documents d left join public.affiliate_files af on af.id=d.affiliate_file_id
  join public.private_assets pa on pa.id=coalesce(d.private_asset_id,af.private_asset_id)
  join storage.objects so on so.bucket_id=pa.storage_bucket and so.name=pa.storage_path
  where d.id=any(coalesce(p_document_ids,array[]::uuid[])) and d.affiliate_id=p_affiliate_id
    and d.status in('PENDING_REVIEW','UNDER_REVIEW','VERIFIED')
  on conflict(request_id,document_type_id) do nothing;
  insert into public.sensitive_change_audit(actor_auth_user_id,affiliate_id,resource,action,target_id,metadata)
  values(p_actor_real_auth_user_id,p_affiliate_id,'program_requests','PROGRAM_PRODUCT_PAYMENT_CONFIRMED',v_row.id,
    jsonb_build_object('program_item_id',v_item.id,'price_source',v_source,'quote_request_id',v_quote.id,
      'payment_count',p_term,'payment_period',v_period,'assisted',v_ctx.id is not null));
  return v_row;
exception when unique_violation then
  select * into v_row from public.program_requests where affiliate_id=p_affiliate_id and idempotency_key=p_idempotency_key;
  if v_row.id is not null and v_row.program_item_id=p_program_item_id and v_row.requested_amount=v_amount
     and v_row.requested_term=p_term and (v_row.financial_submission_snapshot->>'down_payment')::numeric=round(p_down_payment,2) then
    return v_row;
  end if;
  raise;
end $function$

CREATE OR REPLACE FUNCTION public.record_program_request_admin_action(p_request_id uuid, p_action text, p_comment text, p_client_action_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_request public.program_requests%rowtype;v_existing public.program_request_admin_events%rowtype;
  v_event public.program_request_admin_events%rowtype;v_action text:=upper(btrim(coalesce(p_action,'')));
  v_comment text:=nullif(btrim(coalesce(p_comment,'')),'');v_to_status text;v_actor_label text;
  v_from_stage uuid;v_to_stage uuid;
begin
  if auth.uid() is null or not public.has_admin_permission('program_requests.write') then raise exception 'PROGRAM_REQUEST_WRITE_DENIED' using errcode='42501'; end if;
  if p_client_action_id is null then raise exception 'CLIENT_ACTION_ID_REQUIRED' using errcode='22023'; end if;
  if v_action not in('COMMENT','MARK_IN_REVIEW','REJECT','CANCEL') then raise exception 'PROGRAM_REQUEST_ACTION_INVALID' using errcode='22023'; end if;
  if v_comment is not null and length(v_comment) not between 3 and 2000 then raise exception 'PROGRAM_REQUEST_COMMENT_INVALID' using errcode='22023'; end if;
  if v_action in('COMMENT','REJECT','CANCEL') and v_comment is null then raise exception 'PROGRAM_REQUEST_COMMENT_REQUIRED' using errcode='22023'; end if;
  select * into v_existing from public.program_request_admin_events where client_action_id=p_client_action_id;
  if v_existing.id is not null then
    if v_existing.request_id<>p_request_id or v_existing.actor_auth_user_id<>auth.uid() or v_existing.action<>v_action then raise exception 'CLIENT_ACTION_ID_CONFLICT' using errcode='23505'; end if;
    return to_jsonb(v_existing)-'actor_auth_user_id'-'client_action_id';
  end if;
  select * into v_request from public.program_requests where id=p_request_id for update;
  if v_request.id is null then raise exception 'PROGRAM_REQUEST_NOT_FOUND' using errcode='P0001'; end if;
  if v_action<>'COMMENT' and (v_request.financial_approval_snapshot is not null or v_request.status='approved') then raise exception 'APPROVED_FINANCIAL_REQUEST_STATUS_IMMUTABLE' using errcode='P0001'; end if;
  v_from_stage:=nullif(public.resolve_program_request_workflow_state(v_request.id)->>'current_stage_id','')::uuid;
  v_to_status:=v_request.status;
  if v_action='MARK_IN_REVIEW' then
    if v_request.status not in('submitted','requires_financial_processing') then raise exception 'FINANCIAL_REQUEST_TRANSITION_INVALID' using errcode='P0001'; end if;
    v_to_status:='in_review';
  elsif v_action='REJECT' then
    if v_request.status not in('submitted','requires_financial_processing','in_review') then raise exception 'FINANCIAL_REQUEST_TRANSITION_INVALID' using errcode='P0001'; end if;
    v_to_status:='rejected';
  elsif v_action='CANCEL' then
    if v_request.status not in('submitted','requires_financial_processing','in_review') then raise exception 'FINANCIAL_REQUEST_TRANSITION_INVALID' using errcode='P0001'; end if;
    v_to_status:='cancelled';
  end if;
  select coalesce(nullif(btrim(raw_user_meta_data->>'display_name'),''),nullif(btrim(raw_user_meta_data->>'full_name'),''),nullif(btrim(raw_user_meta_data->>'name'),''),'Personal autorizado') into v_actor_label from auth.users where id=auth.uid();
  if v_to_status is distinct from v_request.status then update public.program_requests set status=v_to_status,updated_at=now() where id=v_request.id; end if;
  v_to_stage:=nullif(public.resolve_program_request_workflow_state(v_request.id)->>'current_stage_id','')::uuid;
  insert into public.program_request_admin_events(request_id,actor_auth_user_id,actor_label,action,from_status,to_status,comment,client_action_id,from_stage_id,to_stage_id)
  values(v_request.id,auth.uid(),left(coalesce(v_actor_label,'Personal autorizado'),160),v_action,v_request.status,v_to_status,v_comment,p_client_action_id,v_from_stage,v_to_stage)
  returning * into v_event;
  return to_jsonb(v_event)-'actor_auth_user_id'-'client_action_id';
end $function$

CREATE OR REPLACE FUNCTION public.resolve_program_request_workflow_state(p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.program_requests%rowtype;t public.operational_request_tracking%rowtype;v_stages jsonb;v_current text;v_current_order integer;v_current_stage jsonb;v_resolved jsonb;
begin
  select * into r from public.program_requests where id=p_request_id;
  if r.id is null then raise exception 'REQUEST_NOT_FOUND' using errcode='P0001'; end if;
  if auth.role()<>'service_role' and not(
    auth.uid() is not null and (r.affiliate_id=public.get_effective_affiliate_id() or public.has_admin_permission('workflow.read') or public.has_admin_permission('program_requests.read'))
  ) then raise exception 'REQUEST_WORKFLOW_DENIED' using errcode='42501'; end if;
  if r.workflow_snapshot is null then return jsonb_build_object('available',false,'reason','WORKFLOW_SNAPSHOT_MISSING','message','Seguimiento no disponible'); end if;
  select * into t from public.operational_request_tracking where request_id=r.id;
  select coalesce(jsonb_agg(stage order by (stage->>'sort_order')::integer,stage->>'id'),'[]'::jsonb) into v_stages
  from jsonb_array_elements(r.workflow_snapshot->'stages') stage
  where case when r.status in('rejected','cancelled') then stage->>'outcome'<>'success' else stage->>'outcome'<>'failure' end;
  if t.current_stage_id is not null and exists(select 1 from jsonb_array_elements(v_stages) stage where stage->>'id'=t.current_stage_id::text) then
    v_current:=t.current_stage_id::text;
  else
    select stage->>'id' into v_current from jsonb_array_elements(v_stages) stage
    where stage->'status_references'?r.status order by (stage->>'sort_order')::integer,stage->>'id' limit 1;
  end if;
  if v_current is null then return jsonb_build_object('available',false,'reason','WORKFLOW_STATUS_UNMAPPED','message','Seguimiento no disponible'); end if;
  select (stage->>'sort_order')::integer,stage into v_current_order,v_current_stage from jsonb_array_elements(v_stages) stage where stage->>'id'=v_current;
  select coalesce(jsonb_agg(
    stage||jsonb_build_object(
      'state',case when (stage->>'sort_order')::integer<v_current_order then 'done' when stage->>'id'=v_current then 'current' else 'upcoming' end,
      'date',t.stage_dates->>(stage->>'id')
    ) order by (stage->>'sort_order')::integer,stage->>'id'
  ),'[]'::jsonb) into v_resolved from jsonb_array_elements(v_stages) stage;
  return jsonb_strip_nulls(jsonb_build_object(
    'available',true,'workflow_id',r.workflow_id,'workflow_version',r.workflow_version,
    'workflow_name',r.workflow_snapshot->>'workflow_name','workflow_description',r.workflow_snapshot->>'workflow_description',
    'request_status',r.status,'current_stage_id',v_current,'current_stage',v_current_stage,
    'active_note',nullif(v_current_stage->>'description',''),'stages',v_resolved
  ));
end $function$

CREATE OR REPLACE FUNCTION public.sync_program_request_tracking_from_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_stage jsonb;v_first jsonb;v_dates jsonb;v_at timestamptz;
begin
  select s into v_stage from jsonb_array_elements(new.workflow_snapshot->'stages') s
  where s->'status_references'?new.status
    and (case when new.status in('rejected','cancelled') then s->>'outcome'<>'success' else s->>'outcome'<>'failure' end)
  order by (s->>'sort_order')::integer,s->>'id' limit 1;
  if v_stage is null then raise exception 'REQUEST_WORKFLOW_STATUS_UNMAPPED' using errcode='22023'; end if;
  select s into v_first from jsonb_array_elements(new.workflow_snapshot->'stages') s
    order by (s->>'sort_order')::integer,s->>'id' limit 1;
  select coalesce(stage_dates,'{}'::jsonb) into v_dates from public.operational_request_tracking where request_id=new.id;
  v_dates:=coalesce(v_dates,'{}'::jsonb);
  if coalesce((v_first->>'captures_date')::boolean,false) and not(v_dates?(v_first->>'id')) then
    v_dates:=v_dates||jsonb_build_object(v_first->>'id',new.created_at);
  end if;
  v_at:=case when tg_op='INSERT' then new.created_at else now() end;
  if coalesce((v_stage->>'captures_date')::boolean,false) and not(v_dates?(v_stage->>'id')) then
    v_dates:=v_dates||jsonb_build_object(v_stage->>'id',v_at);
  end if;
  perform set_config('app.workflow_change_reason',case when tg_op='INSERT' then 'Alta de solicitud' else 'Estado de solicitud: '||old.status||' -> '||new.status end,true);
  insert into public.operational_request_tracking(request_id,workflow_id,current_stage_id,stage_dates)
  values(new.id,new.workflow_id,(v_stage->>'id')::uuid,v_dates)
  on conflict(request_id) do update set workflow_id=excluded.workflow_id,current_stage_id=excluded.current_stage_id,stage_dates=excluded.stage_dates;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.transition_program_request_workflow(p_request_id uuid, p_action text, p_comment text, p_client_action_id uuid, p_quote_amount numeric DEFAULT NULL::numeric, p_quote_valid_until date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_request public.program_requests%rowtype;v_existing public.program_request_admin_events%rowtype;
  v_event public.program_request_admin_events%rowtype;v_state jsonb;v_current jsonb;v_target jsonb;v_first jsonb;
  v_action text:=upper(btrim(coalesce(p_action,'')));v_event_action text;v_comment text:=nullif(btrim(coalesce(p_comment,'')),'');
  v_to_status text;v_actor_label text;v_dates jsonb;v_expected_existing text[];
begin
  if auth.uid() is null or not public.has_admin_permission('program_requests.write') then
    raise exception 'PROGRAM_REQUEST_WRITE_DENIED' using errcode='42501';
  end if;
  if p_client_action_id is null then raise exception 'CLIENT_ACTION_ID_REQUIRED' using errcode='22023'; end if;
  if v_action not in('ADVANCE','REJECT') then raise exception 'PROGRAM_REQUEST_WORKFLOW_ACTION_INVALID' using errcode='22023'; end if;
  if v_comment is not null and length(v_comment) not between 3 and 2000 then raise exception 'PROGRAM_REQUEST_COMMENT_INVALID' using errcode='22023'; end if;
  if v_action='REJECT' and v_comment is null then raise exception 'PROGRAM_REQUEST_COMMENT_REQUIRED' using errcode='22023'; end if;

  select * into v_existing from public.program_request_admin_events where client_action_id=p_client_action_id;
  if v_existing.id is not null then
    v_expected_existing:=case when v_action='REJECT' then array['REJECT'] else array['APPROVE','ADVANCE_STAGE'] end;
    if v_existing.request_id<>p_request_id or v_existing.actor_auth_user_id<>auth.uid() or not(v_existing.action=any(v_expected_existing)) then
      raise exception 'CLIENT_ACTION_ID_CONFLICT' using errcode='23505';
    end if;
    return jsonb_build_object('idempotent',true,'event',to_jsonb(v_existing)-'actor_auth_user_id'-'client_action_id',
      'workflow_state',public.resolve_program_request_workflow_state(p_request_id));
  end if;

  select * into v_request from public.program_requests where id=p_request_id for update;
  if v_request.id is null then raise exception 'PROGRAM_REQUEST_NOT_FOUND' using errcode='P0001'; end if;
  v_state:=public.resolve_program_request_workflow_state(v_request.id);
  if not coalesce((v_state->>'available')::boolean,false) then raise exception 'REQUEST_WORKFLOW_UNAVAILABLE' using errcode='P0001'; end if;
  v_current:=v_state->'current_stage';
  if v_current is null then raise exception 'REQUEST_WORKFLOW_CURRENT_STAGE_MISSING' using errcode='P0001'; end if;

  if v_action='REJECT' then
    if v_request.status in('approved','rejected','cancelled') then raise exception 'FINANCIAL_REQUEST_TRANSITION_INVALID' using errcode='P0001'; end if;
    select s into v_target from jsonb_array_elements(v_request.workflow_snapshot->'stages') s
      where s->>'outcome'='failure' and s->'status_references'?'rejected'
      order by (s->>'sort_order')::integer,s->>'id' limit 1;
    if v_target is null then raise exception 'REQUEST_WORKFLOW_REJECT_STAGE_MISSING' using errcode='P0001'; end if;
    v_to_status:='rejected';v_event_action:='REJECT';
  else
    if v_request.status in('rejected','cancelled') then raise exception 'FINANCIAL_REQUEST_TRANSITION_INVALID' using errcode='P0001'; end if;
    select s into v_target from jsonb_array_elements(v_state->'stages') s
      where (s->>'sort_order')::integer>(v_current->>'sort_order')::integer and s->>'outcome'<>'failure'
      order by (s->>'sort_order')::integer,s->>'id' limit 1;
    if v_target is null then raise exception 'REQUEST_WORKFLOW_ALREADY_COMPLETE' using errcode='P0001'; end if;
    v_to_status:=v_request.status;
    if v_target->'status_references'?'approved' then
      if v_request.financial_processing_status is not null then
        raise exception 'SPECIALIZED_FINANCIAL_APPROVAL_REQUIRED' using errcode='P0001';
      elsif v_request.request_type='quote' then
        if p_quote_amount is null or p_quote_amount<=0 then raise exception 'QUOTE_AMOUNT_REQUIRED' using errcode='22023'; end if;
      end if;
      v_to_status:='approved';v_event_action:='APPROVE';
    elsif v_target->'status_references'?'in_review' and v_request.status in('submitted','requires_financial_processing') then
      v_to_status:='in_review';v_event_action:='ADVANCE_STAGE';
    else v_event_action:='ADVANCE_STAGE'; end if;
  end if;

  select coalesce(nullif(btrim(raw_user_meta_data->>'display_name'),''),nullif(btrim(raw_user_meta_data->>'full_name'),''),
    nullif(btrim(raw_user_meta_data->>'name'),''),'Personal autorizado') into v_actor_label from auth.users where id=auth.uid();
  perform set_config('app.workflow_change_reason',coalesce(v_comment,case when v_action='REJECT' then 'Rechazo de etapa' else 'Avance de etapa' end),true);

  if v_to_status is distinct from v_request.status then
    if v_request.request_type='quote' and v_to_status='approved' then
      update public.program_requests set status='approved',quoted_amount=round(p_quote_amount,2),quote_note=v_comment,
        valid_until=coalesce(p_quote_valid_until,current_date+15),responded_by_auth_user_id=auth.uid(),responded_at=now(),seen_at=null,updated_at=now()
      where id=v_request.id;
    else
      update public.program_requests set status=v_to_status,updated_at=now() where id=v_request.id;
    end if;
  else
    select coalesce(stage_dates,'{}'::jsonb) into v_dates from public.operational_request_tracking where request_id=v_request.id;
    v_dates:=coalesce(v_dates,'{}'::jsonb);
    select s into v_first from jsonb_array_elements(v_request.workflow_snapshot->'stages') s order by (s->>'sort_order')::integer,s->>'id' limit 1;
    if coalesce((v_first->>'captures_date')::boolean,false) and not(v_dates?(v_first->>'id')) then v_dates:=v_dates||jsonb_build_object(v_first->>'id',v_request.created_at); end if;
    if coalesce((v_target->>'captures_date')::boolean,false) and not(v_dates?(v_target->>'id')) then v_dates:=v_dates||jsonb_build_object(v_target->>'id',now()); end if;
    insert into public.operational_request_tracking(request_id,workflow_id,current_stage_id,stage_dates)
      values(v_request.id,v_request.workflow_id,(v_target->>'id')::uuid,v_dates)
      on conflict(request_id) do update set workflow_id=excluded.workflow_id,current_stage_id=excluded.current_stage_id,stage_dates=excluded.stage_dates;
  end if;

  insert into public.program_request_admin_events(
    request_id,actor_auth_user_id,actor_label,action,from_status,to_status,comment,client_action_id,from_stage_id,to_stage_id
  ) values(v_request.id,auth.uid(),left(coalesce(v_actor_label,'Personal autorizado'),160),v_event_action,v_request.status,v_to_status,
    v_comment,p_client_action_id,(v_current->>'id')::uuid,(v_target->>'id')::uuid) returning * into v_event;
  return jsonb_build_object('idempotent',false,'event',to_jsonb(v_event)-'actor_auth_user_id'-'client_action_id',
    'workflow_state',public.resolve_program_request_workflow_state(v_request.id));
end $function$

CREATE OR REPLACE FUNCTION public.validate_operational_request_tracking()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_snapshot jsonb;v_status text;v_stage jsonb;
begin
  select workflow_snapshot,status into v_snapshot,v_status from public.program_requests where id=new.request_id;
  if v_snapshot is null or (v_snapshot->>'workflow_id')::uuid is distinct from new.workflow_id then
    raise exception 'REQUEST_TRACKING_WORKFLOW_MISMATCH' using errcode='22023';
  end if;
  if new.current_stage_id is not null then
    select s into v_stage from jsonb_array_elements(v_snapshot->'stages') s where (s->>'id')::uuid=new.current_stage_id;
    if v_stage is null then raise exception 'REQUEST_TRACKING_STAGE_MISMATCH' using errcode='22023'; end if;
    if not (
      coalesce(v_stage->>'outcome','process')='process' and v_status in('submitted','in_review','requires_financial_processing') or
      coalesce(v_stage->>'outcome','process')='success' and v_status='approved' or
      coalesce(v_stage->>'outcome','process')='failure' and v_status in('rejected','cancelled')
    ) then raise exception 'REQUEST_TRACKING_STATUS_MISMATCH' using errcode='22023'; end if;
  end if;
  if exists(select 1 from jsonb_object_keys(coalesce(new.stage_dates,'{}'::jsonb)) key where not exists(select 1 from jsonb_array_elements(v_snapshot->'stages') s where s->>'id'=key)) then
    raise exception 'REQUEST_TRACKING_DATE_STAGE_MISMATCH' using errcode='22023';
  end if;
  return new;
end $function$
